import{_ as t,o as a,c as i,ap as s}from"./chunks/framework.CuFS6FqL.js";const p=JSON.parse('{"title":"Onboarding handout","description":"Copy-pasteable boilerplate for new hires covering equipment confirmation, usage rules, and setup checklists for accounts, laptop, smartphone, and YubiKey.","frontmatter":{"title":"Onboarding handout","description":"Copy-pasteable boilerplate for new hires covering equipment confirmation, usage rules, and setup checklists for accounts, laptop, smartphone, and YubiKey.","additional_information":"The handbook URLs are absolute URLs by intention because the boilerplate is meant to be copy/pasted as markdown"},"headers":[],"relativePath":"organization/human-resources/onboarding-handout.md","filePath":"organization/human-resources/onboarding-handout.md"}'),l={name:"organization/human-resources/onboarding-handout.md"};function o(r,e,n,c,u,h){return a(),i("div",null,[...e[0]||(e[0]=[s('<div style="display:none;" hidden="true" aria-hidden="true">Are you an LLM? You can read better optimized documentation at /organization/human-resources/onboarding-handout.md for this page in Markdown format</div><h1 id="onboarding-handout-boilerplate" tabindex="-1">Onboarding handout (boilerplate) <a class="header-anchor" href="#onboarding-handout-boilerplate" aria-label="Permalink to &quot;Onboarding handout (boilerplate)&quot;">​</a></h1><h2 id="confirmation" tabindex="-1">Confirmation <a class="header-anchor" href="#confirmation" aria-label="Permalink to &quot;Confirmation&quot;">​</a></h2><p>I confirm that I have received:</p><ul><li>Laptop (Model TODO) + Sleeve</li><li>Smartphone (Model TODO)</li><li>2 Yubikeys</li></ul><h2 id="guidance" tabindex="-1">Guidance <a class="header-anchor" href="#guidance" aria-label="Permalink to &quot;Guidance&quot;">​</a></h2><ul><li>The equipment and accounts must be used for work-related tasks only. Private usage is not allowed.</li><li>If you lose equipment, please notify us immediately.</li></ul><h3 id="documentation" tabindex="-1">Documentation <a class="header-anchor" href="#documentation" aria-label="Permalink to &quot;Documentation&quot;">​</a></h3><p>You find most of our documentation in our...</p><ul><li><a href="https://handbook.syslifters.com/" target="_blank" rel="noreferrer">public handbook</a></li><li><a href="https://syslifters.sysre.pt/projects/5086e509-4fca-4d99-aa2a-404feeda69a7/notes/" target="_blank" rel="noreferrer">internal knowledge base</a></li></ul><p>We are a <a href="https://handbook.syslifters.com/about-the-handbook" target="_blank" rel="noreferrer">public first</a> company and document everything in public, except if we have a good reason for keeping it private. Take your time to skim and read through topics that you find interesting.</p><p>We try to keep our documentation up to date. This is a shared responsibility. If you spot errors, find room for improvement, missing topics that should be documented, please feel empowered to update it.<br> This is especially important, as you bring your own views and ideas into our company, while we might already be blind or act on unwritten conventions that you as our new colleague cannot know if undocumented.</p><p>You find the sources of our handbook in our <a href="https://gitlab.internal.syslifters.com/docs/public" target="_blank" rel="noreferrer">GitLab</a>. Follow our <a href="https://handbook.syslifters.com/making-changes" target="_blank" rel="noreferrer">making changes</a> guide. If in doubt, ask your colleagues.</p><h3 id="accounts" tabindex="-1">Accounts <a class="header-anchor" href="#accounts" aria-label="Permalink to &quot;Accounts&quot;">​</a></h3><ul><li>Use new passwords for all accounts. Never reuse previously used passwords.</li><li>Never use passwords of work-related accounts for private accounts.</li><li>Use our password manager at <a href="https://vaultwarden.external.syslifters.com/" target="_blank" rel="noreferrer">https://vaultwarden.external.syslifters.com/</a><ul><li>Never enter your password manager master password on private devices.</li><li>Optional: Create an emergency contact in Vaultwarden</li></ul></li><li>Use MFA for all accounts (incl. your password manager).</li><li>Use both Yubikeys for all accounts to prevent lockout in case of loss.</li><li>Do not store MFA data in your password manager.</li><li>Use the following MFA mechanisms in descending order of preference: <ul><li>FIDO2</li><li>Yubico OTP</li><li>TOTP</li></ul></li></ul><h3 id="laptop" tabindex="-1">Laptop <a class="header-anchor" href="#laptop" aria-label="Permalink to &quot;Laptop&quot;">​</a></h3><h4 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h4><ul><li>We use local users for login <ul><li>You are allowed to use biometrics (e.g., face, fingerprint)</li></ul></li><li>Sync your important data to NextCloud (e.g., specific folders)</li></ul><h4 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Make sure the hard drive is encrypted using BitLocker and PIN (no TPM only)</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Make sure AV/EDR (IKARUS/Harfanglabs) is installed and active</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> create a vaultwarden account at <a href="https://vaultwarden.external.syslifters.com/" target="_blank" rel="noreferrer">https://vaultwarden.external.syslifters.com/</a></li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Install the following software packages (or check if installed) <ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Tailscale client for VPN (your client must be unlocked on the server on the first connection)</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Signal messenger <ul><li>Connect with your work-related Signal account</li></ul></li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> OnlyOffice Desktop App</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Docker Desktop <ul><li>Needed for our &quot;pentestbox&quot;. Follow <a href="https://handbook.syslifters.com/organization/human-resources/pentestbox-setup" target="_blank" rel="noreferrer">setup guide</a></li><li>(incl. Microsoft WSL2)</li></ul></li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Burp Professional <ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Install Extensions listed <a href="https://handbook.syslifters.com/pentesting-manual/pentesting-toolset" target="_blank" rel="noreferrer">here</a></li></ul></li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> YubiKey Authenticator</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> emClient (recommended) or Thunderbird <ul><li>Create app password via <a href="https://mail.internal.syslifters.com/" target="_blank" rel="noreferrer">email management</a></li><li>Follow <a href="https://handbook.syslifters.com/organization/human-resources/email-setup" target="_blank" rel="noreferrer">setup guide</a></li></ul></li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Claude Code CLI <ul><li>Follow <a href="https://handbook.syslifters.com/organization/human-resources/ai-tool-setup" target="_blank" rel="noreferrer">setup guide</a></li></ul></li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Set up &quot;Project Sense&quot; for project retention <ul><li>Follow <a href="https://handbook.syslifters.com/organization/human-resources/project-retention" target="_blank" rel="noreferrer">setup guide</a></li></ul></li></ul></li></ul><p>Additional optional software:</p><ul><li>Notepad++</li><li>7zip</li><li>Python</li><li>Visual Studio Code</li><li>Cursor</li><li>VirtualBox</li><li>GNU Privacy Guard</li><li>Meld</li><li>Flameshot</li><li>VLC media player</li><li>Wireshark</li><li>Microsoft Teams</li></ul><h3 id="smartphone" tabindex="-1">Smartphone <a class="header-anchor" href="#smartphone" aria-label="Permalink to &quot;Smartphone&quot;">​</a></h3><h4 id="usage-1" tabindex="-1">Usage <a class="header-anchor" href="#usage-1" aria-label="Permalink to &quot;Usage&quot;">​</a></h4><ul><li>Never mix private and work-related accounts</li><li>Use MFA for Google, Samsung accounts (FIDO2)</li><li>Use sensitive apps in the secure folder only <ul><li>Password managers</li><li>Authenticator apps (Yubico Authenticator)</li></ul></li><li>Use disappearing messages in messengers <ul><li>Also with customers</li><li>Four weeks by default</li><li>Max. 1 day for sensitive information (like passwords; less if possible)</li></ul></li><li>The device is not meant to be used as a device for pentesting apps <ul><li>Do not install custom certificates or debugging tools for pentest purposes</li><li>Do not unlock the bootloader or root your device</li></ul></li></ul><h4 id="setup-1" tabindex="-1">Setup <a class="header-anchor" href="#setup-1" aria-label="Permalink to &quot;Setup&quot;">​</a></h4><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Create a new work-related Play Store account</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Create a new work-related Samsung account</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Enable Secure Folders (Samsung Knox)</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Install Signal messenger</li></ul><h3 id="external-drives" tabindex="-1">External drives <a class="header-anchor" href="#external-drives" aria-label="Permalink to &quot;External drives&quot;">​</a></h3><ul><li>You receive an external drive at request</li><li>External drives (hard drives, USB drives, etc.) must be encrypted using BitLocker and a long-enough password</li><li>Never connect your external hard drive at non-work-related devices or customer equipment if used for backups</li><li>After connecting drives to potentially untrusted devices (e.g., customer equipment), consider formatting the device. In any case, change the BitLocker password if you entered it on the customer device.</li></ul><h3 id="yubikey" tabindex="-1">YubiKey <a class="header-anchor" href="#yubikey" aria-label="Permalink to &quot;YubiKey&quot;">​</a></h3><h4 id="usage-2" tabindex="-1">Usage <a class="header-anchor" href="#usage-2" aria-label="Permalink to &quot;Usage&quot;">​</a></h4><ul><li>Use PIV or GPG for SSH authentication (prefer PIV) <ul><li>See our <a href="https://handbook.syslifters.com/organization/human-resources/yubikey-setup" target="_blank" rel="noreferrer">setup guide</a></li></ul></li><li>Private keys should never leave the key</li><li>Always setup both of your YubiKey: <ul><li>One primary</li><li>One backup key</li></ul></li><li>Leave the backup key at your main work place (don&#39;t carry it to customers to lose both at the same time)</li><li>Always use the longest possible key lengths</li><li>Store secrets (PIN, PUK, etc) in Vaultwarden</li><li>Add a password to protect TOTP accounts if you have any</li><li>If you use the GPG module, change PIN, PUK and the admin key</li><li>If you use the PIV module, change PIN, PUK and the management key</li></ul><h4 id="setup-2" tabindex="-1">Setup <a class="header-anchor" href="#setup-2" aria-label="Permalink to &quot;Setup&quot;">​</a></h4><p>On both SSH keys:</p><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> <a href="https://www.yubico.com/genuine/" target="_blank" rel="noreferrer">Verify your Yubikey</a></li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Set a FIDO2 PIN (via Yubico Authenticator/Passkeys)</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Set PIV PIN, PUK and Management Key</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Set GPG PIN, PUK, admin key</li><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Generate certificates for SSH authentication (e.g., on slot 9a). Use <a href="https://handbook.syslifters.com/organization/human-resources/yubikey-setup" target="_blank" rel="noreferrer">this</a> guide.</li></ul><h2 id="misc" tabindex="-1">MISC <a class="header-anchor" href="#misc" aria-label="Permalink to &quot;MISC&quot;">​</a></h2><p>Do this, after you have completed this checklist:</p><ul class="contains-task-list"><li class="task-list-item enabled"><input class="task-list-item-checkbox" type="checkbox"> Generate Archiving Key for Sysreptor <a href="https://syslifters.sysre.pt/users/self/publickeys/" target="_blank" rel="noreferrer">here</a> using the yubikey</li></ul><h2 id="links-and-resources" tabindex="-1">Links and resources <a class="header-anchor" href="#links-and-resources" aria-label="Permalink to &quot;Links and resources&quot;">​</a></h2><ul><li>Account management: <a href="https://login.syslifters.com/" target="_blank" rel="noreferrer">https://login.syslifters.com/</a></li><li>Password Manager: <a href="https://vaultwarden.external.syslifters.com/" target="_blank" rel="noreferrer">https://vaultwarden.external.syslifters.com/</a></li><li>NextCloud (E-Mails, Files, Talk, etc.): <a href="https://cloud.syslifters.com/" target="_blank" rel="noreferrer">https://cloud.syslifters.com/</a></li><li>E-Mail account management: <a href="https://mail.internal.syslifters.com/" target="_blank" rel="noreferrer">https://mail.internal.syslifters.com/</a></li><li>Mailserver (SMTP/IMAP): mail.syslifters.com</li><li>GitLab: <a href="https://gitlab.internal.syslifters.com/" target="_blank" rel="noreferrer">https://gitlab.internal.syslifters.com/</a></li><li>SysReptor: <a href="https://syslifters.sysre.pt" target="_blank" rel="noreferrer">https://syslifters.sysre.pt</a></li><li>LXCBox: <a href="https://lxcbox.internal.syslifters.com/" target="_blank" rel="noreferrer">https://lxcbox.internal.syslifters.com/</a></li><li>PentestAI: <a href="https://pentestai.internal.syslifters.com/" target="_blank" rel="noreferrer">https://pentestai.internal.syslifters.com/</a></li><li>Handbook/Pentesting Manual: <a href="https://handbook.syslifters.com/pentesting-manual/" target="_blank" rel="noreferrer">https://handbook.syslifters.com/pentesting-manual/</a></li><li>Handbook/Organization: <a href="https://handbook.syslifters.com/organization/" target="_blank" rel="noreferrer">https://handbook.syslifters.com/organization/</a></li></ul>',40)])])}const b=t(l,[["render",o]]);export{p as __pageData,b as default};
